import {
  type KeyboardEvent,
  type PointerEvent,
  useCallback,
  useRef,
  useState,
} from "react";
import { flushSync } from "react-dom";
import { startSortableDrag } from "@/lib/sortable-drag";

/** The nearest ancestor that scrolls vertically, or null for the page. */
function verticalScroller(node: HTMLElement): HTMLElement | null {
  for (let parent = node.parentElement; parent; parent = parent.parentElement) {
    const { overflowY } = getComputedStyle(parent);
    if (
      (overflowY === "auto" || overflowY === "scroll") &&
      parent.scrollHeight > parent.clientHeight
    ) {
      return parent;
    }
  }
  return null;
}

/** The copy of a track's header that follows the pointer: draw it fixed, at this box, with `ref` on it. */
export interface TrackGhost {
  height: number;
  id: string;
  left: number;
  top: number;
  width: number;
}

/**
 * Reorders the tracks of a timeline: drag a track's grip to move it, or
 * press Up or Down on it. Give each grip `gripProps(id)`; it must sit inside
 * the `Timeline`, in its track's row. While a track is dragged the other rows
 * slide aside for it, and `ghost` is the copy of its header to draw under the
 * pointer: the drag moves them straight in the DOM, so a move costs no render.
 * The view scrolls when the pointer nears its top or bottom edge.
 */
export function useTrackReorder({
  blockOf,
  onMove,
  order,
}: {
  /** The tracks that move with a track, itself first: a group with what is in it. @default the track alone */
  blockOf?: (id: string) => readonly string[];
  /** A track was dropped at `index`, counted once it has left its place. */
  onMove: (id: string, index: number) => void;
  /** The tracks' ids, top to bottom. */
  order: readonly string[];
}) {
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [ghost, setGhost] = useState<TrackGhost | null>(null);
  const ghostRef = useRef<HTMLDivElement>(null);
  const live = useRef({ blockOf, onMove, order });
  live.current = { blockOf, onMove, order };

  const startDrag = useCallback((event: PointerEvent<HTMLElement>) => {
    if (event.button !== 0) {
      return;
    }
    event.preventDefault();
    const id = event.currentTarget.dataset.trackGrip ?? "";
    const row = event.currentTarget.closest<HTMLElement>(
      '[data-slot="timeline-track"]'
    );
    const timeline = event.currentTarget.closest<HTMLElement>(
      '[data-slot="timeline"]'
    );
    if (!(row && timeline)) {
      return;
    }
    const grips = Array.from(
      timeline.querySelectorAll<HTMLElement>("[data-track-grip]")
    );
    const items = grips.flatMap((grip) => {
      const own = grip.closest<HTMLElement>('[data-slot="timeline-track"]');
      return own ? [own] : [];
    });
    const from = items.indexOf(row);
    const block = new Set(live.current.blockOf?.(id) ?? [id]);
    const count = grips.filter((grip) =>
      block.has(grip.dataset.trackGrip ?? "")
    ).length;
    const box = row.getBoundingClientRect();
    // The copy is the track's header, the column the name and the controls sit in.
    const header = (
      row.querySelector<HTMLElement>('[data-slot="timeline-track-header"]') ??
      row
    ).getBoundingClientRect();
    startSortableDrag({
      axis: "y",
      count: Math.max(count, 1),
      from,
      ghost: () => ghostRef.current,
      items,
      // In the frame the copy goes, the new order is there: one without either would jump.
      onEnd: (landed) =>
        flushSync(() => {
          setGhost(null);
          setDraggingId(null);
          if (landed !== null) {
            live.current.onMove(id, landed);
          }
        }),
      onLift: () => {
        setGhost({
          height: box.height,
          id,
          left: header.left,
          top: box.top,
          width: header.width,
        });
        setDraggingId(id);
      },
      scroller: verticalScroller(row),
      x: event.clientX,
      y: event.clientY,
    });
  }, []);

  const nudge = useCallback((event: KeyboardEvent<HTMLElement>) => {
    const id = event.currentTarget.dataset.trackGrip ?? "";
    const from = live.current.order.indexOf(id);
    const direction = { ArrowDown: 1, ArrowUp: -1 }[event.key];
    if (from === -1 || !direction) {
      return;
    }
    event.preventDefault();
    live.current.onMove(id, from + direction);
  }, []);

  const gripProps = useCallback(
    (id: string) => ({
      "data-track-grip": id,
      onKeyDown: nudge,
      onPointerDown: startDrag,
    }),
    [nudge, startDrag]
  );

  return { draggingId, ghost, ghostRef, gripProps };
}

import type { ComponentProps, CSSProperties, Ref } from "react";
import { createPortal } from "react-dom";
import { cn } from "@/lib/utils";
import type { TrackGhost } from "@/hooks/use-track-reorder";

/**
 * The grip a track is moved by, down the left edge of its header: give it
 * `gripProps(id)` from `useTrackReorder`. Drag it, or press Up and Down on it.
 */
function TrackGrip({
  className,
  dragging,
  trackName,
  ...props
}: ComponentProps<"button"> & {
  /** Whether its track is the one being dragged. */
  dragging?: boolean;
  trackName: string;
}) {
  return (
    <button
      aria-label={`Move ${trackName}`}
      className={cn(
        "absolute inset-y-0 inset-s-1 z-10 flex w-3 cursor-grab items-center justify-center text-muted-foreground/60 transition-colors hover:bg-muted/60 hover:text-foreground focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring focus-visible:outline-none active:cursor-grabbing",
        dragging && "cursor-grabbing bg-muted text-foreground",
        className
      )}
      data-slot="track-grip"
      type="button"
      {...props}
    >
      <svg
        aria-hidden="true"
        className="size-3.5"
        fill="currentColor"
        focusable="false"
        viewBox="0 0 16 16"
      >
        <circle cx="5.5" cy="3.5" r="1.25" />
        <circle cx="10.5" cy="3.5" r="1.25" />
        <circle cx="5.5" cy="8" r="1.25" />
        <circle cx="10.5" cy="8" r="1.25" />
        <circle cx="5.5" cy="12.5" r="1.25" />
        <circle cx="10.5" cy="12.5" r="1.25" />
      </svg>
    </button>
  );
}

/**
 * The copy of a track's header under the pointer while it is dragged, drawn
 * over the page: give it `ghost` and `ghostRef` from `useTrackReorder`, and
 * the track's name. Nothing while no track is dragged.
 */
function TrackReorderGhost({
  className,
  ghost,
  ghostRef,
  style,
  trackName,
}: {
  className?: string;
  ghost: TrackGhost | null;
  ghostRef: Ref<HTMLDivElement>;
  /** What carries the color of a track that has one of its own, as `trackSwatch` gives it. */
  style?: CSSProperties;
  trackName?: string;
}) {
  if (!(ghost && trackName)) {
    return null;
  }
  return createPortal(
    <div
      aria-hidden="true"
      className={cn(
        "pointer-events-none fixed z-50 flex items-center border border-s-4 bg-card px-3 text-sm shadow-lg",
        className
      )}
      data-slot="track-reorder-ghost"
      ref={ghostRef}
      style={{
        ...style,
        height: ghost.height,
        left: ghost.left,
        top: ghost.top,
        width: ghost.width,
      }}
    >
      {trackName}
    </div>,
    document.body
  );
}

export { TrackGrip, TrackReorderGhost };
